    'FluxVectorController/SpeedFluxObserver', 'SpeedFluxObserver (motulator)', 'Flux observer with speed estimation, created by create_speed_flux_observer. The mask initialization resolves the defaults of create_speed_flux_observer and computes the gains of the SpeedObserver and the FluxObserver inside it, as in SpeedFluxObserver. The machine model par is a struct with the fields n_p, R_s, L_d, L_q, and psi_f of SynchronousMachinePars, or n_p, R_s, and psi_s_dq_fcn (a GradNet flux map) of SaturatedSynchronousMachinePars.', strjoin({ ...
    '% Default speed estimation poles of create_speed_flux_observer', ...
    '% (default_alpha_o). With J, the triple pole at alpha_o/sqrt(3) keeps the', ...
    '% speed gain about the same.', ...
    'alpha_o_obs = alpha_o;', ...
    'if isempty(alpha_o_obs)', ...
    '  if sensorless', ...
    '    alpha_o_obs = 2*pi*50;', ...
    '  else', ...
    '    alpha_o_obs = 2*pi*400;', ...
    '  end', ...
    '  if ~isempty(J)', ...
    '    alpha_o_obs = alpha_o_obs/sqrt(3);', ...
    '  end', ...
    'end', ...
    '% Default observer gain of create_speed_flux_observer, k_o(w_m) = k0 +', ...
    '% k1*abs(w_m) (k0 = NaN: sigma0 of the machine model, see the FluxObserver)', ...
    'k_o_obs = k_o;', ...
    'if isempty(k_o_obs)', ...
    '  if sensorless', ...
    '    k_o_obs = [NaN 0.2];', ...
    '  else', ...
    '    k_o_obs = [2*pi*15 0];', ...
    '  end', ...
    'end', ...
    '% Gains for critically damped dynamics (SpeedFluxObserver.__init__), the', ...
    '% pole matched to the sampling period (matched_pole)', ...
    'alpha_o_obs = -expm1(-alpha_o_obs*T_s)/T_s;', ...
    'if isempty(J)', ...
    '  k_theta = 2*alpha_o_obs;', ...
    '  k_w = alpha_o_obs^2;', ...
    '  k_tau = 0;', ...
    'else', ...
    '  k_theta = 3*alpha_o_obs;', ...
    '  k_w = 3*alpha_o_obs^2;', ...
    '  k_tau = J*alpha_o_obs^3;', ...
    'end', ...
    '% Weight of the measured rotor angle in the FluxObserver (position_error)', ...
    'h = 1 - sensorless;'}, newline), { ...
    'par', 'par: Machine model (SynchronousMachinePars, or SaturatedSynchronousMachinePars with a GradNet flux map psi_s_dq_fcn) as a struct', 'par'
    'alpha_o', 'alpha_o: Speed estimation poles (rad/s), [] = default', 'cfg.alpha_o'
    'k_o', 'k_o: Observer gain [k0 k1], k_o(w_m) = k0 + k1*abs(w_m), [] = default', 'cfg.k_o'
    'k_f', 'k_f: PM-flux estimation gain, only [] (zero)', 'cfg.k_f'
    'sensorless', 'sensorless: Sensorless mode (1) or sensored mode (0)', 'cfg.sensorless'
    'J', 'J: Inertia (kgm^2), [] = the model not used', 'cfg.J'
    'T_s', 'T_s: Sampling period (s)', 'cfg.T_s'
    }, strjoin({ ...
